import{_ as a,o,c as e,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const _=JSON.parse('{"title":"暑期 AI 选修课 · 教学实践","description":"","frontmatter":{},"headers":[],"relativePath":"projects/ai-course.md","filePath":"projects/ai-course.md","lastUpdated":1791119045000}'),s={name:"projects/ai-course.md"};function l(i,t,n,c,u,p){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="暑期-ai-选修课-·-教学实践" tabindex="-1">暑期 AI 选修课 · 教学实践 <a class="header-anchor" href="#暑期-ai-选修课-·-教学实践" aria-label="Permalink to &quot;暑期 AI 选修课 · 教学实践&quot;">​</a></h1><blockquote><p>职业院校 AI 选修课 · 2026 年暑期</p></blockquote><h2 id="课程设计" tabindex="-1">课程设计 <a class="header-anchor" href="#课程设计" aria-label="Permalink to &quot;课程设计&quot;">​</a></h2><p>面向职业院校学生设计的 AI 应用选修课，目标是让学生真正动手把 AI 用起来，而不是停留在概念：</p><ul><li><strong>Day 1 · 论文报告辅助</strong>：以&quot;用 AI 辅助完成一篇论文/报告&quot;为主线，配套完整的提示词集（Prompt 集合）与课上素材包，教学生拆解任务、迭代提示词、核对 AI 给出的答案</li><li><strong>Day 2 · 课程素材包</strong>：延续实践主线，提供结构化的课程素材与练习</li><li><strong>QA 环节</strong>：汇总学生的高频问题形成问答文档</li><li><strong>学生信息库</strong>：用飞书多维表格管理学生信息与学习进度（Demo）</li></ul><h2 id="教学理念" tabindex="-1">教学理念 <a class="header-anchor" href="#教学理念" aria-label="Permalink to &quot;教学理念&quot;">​</a></h2><p>与我的开源内容创作（Jev Cookbook、self-llm 等）同源：<strong>AI 时代的学习不是&quot;拿到答案&quot;，而是建立判断答案对不对的能力。</strong> 课程刻意让学生经历&quot;AI 给了答案 → 我如何验证 → 我如何改进提示 → 我如何对结果负责&quot;的完整闭环。</p><p>2024 年起我已在该校开设系列课程（「第一课」等），持续积累面向零基础学生的 AI 教学方法。</p><ul><li><a href="/projects/">返回项目总览</a></li></ul>',9)])])}const h=a(s,[["render",l]]);export{_ as __pageData,h as default};
